 15→#[derive(Debug, Clone, Serialize, Deserialize)]
 16→pub struct StateStore {
 17→    /// Schema version for migration.
 18→    pub version: u32,
 19→
 20→    /// Project identification.
 21→    pub project: ProjectInfo,
 22→
 23→    /// Last run timestamp.
 24→    pub last_run: Option<DateTime<Utc>>,
 25→
 26→    /// Last workflow executed.
 27→    pub last_workflow: Option<String>,
 28→
 29→    /// State for each step.
 30→    pub steps: HashMap<String, StepState>,
 31→
 32→    /// Run history (most recent first).
 33→    #[serde(default)]
 34→    pub runs: Vec<RunRecord>,
 35→}
 36→
 37→/// Project information stored in state.
 38→#[derive(Debug, Clone, Serialize, Deserialize)]
 39→pub struct ProjectInfo {
 40→    pub path: String,
 41→    pub git_remote: Option<String>,
 42→    pub name: String,
 43→}
 44→
 45→/// State for a single step.
 46→#[derive(Debug, Clone, Serialize, Deserialize)]
 47→pub struct StepState {
 48→    /// When this step last ran.
 49→    pub last_run: Option<DateTime<Utc>>,
 50→
 51→    /// Status of the last run.
 52→    pub status: StepStatus,
 53→
 54→    /// Duration of the last run in milliseconds.
 55→    pub duration_ms: Option<u64>,
 56→
 57→    /// Hash of watched files at last run.
 58→    pub watches_hash: Option<String>,
 59→}
 60→
 61→/// Status of a step execution.
 62→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 63→pub enum StepStatus {
 64→    Success,
 65→    Failed,
 66→    Skipped,
 67→    NeverRun,
 68→}
 69→
 70→/// Entry in step history.
 71→#[derive(Debug, Clone)]
 72→pub struct StepHistoryEntry {
 73→    pub timestamp: DateTime<Utc>,
 74→    pub status: StepStatus,
 75→    pub workflow: String,
 76→}
 77→
 78→/// Summary for status command.
 79→#[derive(Debug, Clone)]
 80→pub struct StatusSummary {
 81→    pub last_run: Option<DateTime<Utc>>,
 82→    pub last_workflow: Option<String>,
 83→    pub step_count: usize,
 84→    pub complete_count: usize,
 85→}
 86→
 87→/// Size information for state.
 88→#[derive(Debug, Clone)]
 89→pub struct StateSize {
 90→    pub run_count: usize,
 91→    pub step_count: usize,
 92→}
 93→
 94→impl StateStore {
 95→    /// Current schema version.
 96→    pub const CURRENT_VERSION: u32 = 1;
 97→
 98→    /// Default number of runs to keep.
 99→    pub const DEFAULT_HISTORY_RETENTION: usize = 50;
100→
101→    /// Create a new state store for a project.
102→    pub fn new(project_id: &ProjectId) -> Self {
103→        Self {
104→            version: Self::CURRENT_VERSION,
105→            project: ProjectInfo {
106→                path: project_id.path().to_string_lossy().to_string(),
107→                git_remote: project_id.git_remote().map(String::from),
108→                name: project_id.name().to_string(),
109→            },
110→            last_run: None,
111→            last_workflow: None,
112→            steps: HashMap::new(),
113→            runs: Vec::new(),
114→        }
115→    }
116→
117→    /// Get the state directory for a project.
118→    pub fn state_dir(project_id: &ProjectId) -> PathBuf {
119→        dirs::home_dir()
120→            .unwrap_or_else(|| PathBuf::from("~"))
121→            .join(".bivvy")
122→            .join("projects")
123→            .join(project_id.hash())
124→    }
125→
126→    /// Get the state file path.
127→    pub fn state_file(project_id: &ProjectId) -> PathBuf {
128→        Self::state_dir(project_id).join("state.yml")
129→    }
130→
131→    /// Load state from disk.
132→    pub fn load(project_id: &ProjectId) -> crate::error::Result<Self> {
133→        let path = Self::state_file(project_id);
134→
135→        if !path.exists() {
136→            return Ok(Self::new(project_id));
137→        }
138→
139→        let content = fs::read_to_string(&path)?;
140→        let state: Self = serde_yaml::from_str(&content).map_err(|e| {
141→            crate::error::BivvyError::ConfigParseError {
142→                path: path.clone(),
143→                message: e.to_string(),
144→            }
145→        })?;
146→
147→        Ok(state)
148→    }
149→
150→    /// Save state to disk using atomic write.
151→    ///
152→    /// Uses the write-to-temp-then-rename pattern to prevent corruption
153→    /// if the process crashes or loses power during the write operation.
154→    /// This ensures state files are never partially written.
155→    pub fn save(&self, project_id: &ProjectId) -> crate::error::Result<()> {
156→        let dir = Self::state_dir(project_id);
157→        fs::create_dir_all(&dir)?;
158→
159→        let path = Self::state_file(project_id);
160→        let content = serde_yaml::to_string(self).map_err(|e| {
161→            crate::error::BivvyError::ConfigValidationError {
162→                message: format!("Failed to serialize state: {}", e),
163→            }
164→        })?;
165→
166→        // Atomic write: write to temp file, then rename
167→        // This prevents corruption if process crashes mid-write
168→        let temp_path = path.with_extension("yml.tmp");
169→        fs::write(&temp_path, &content)?;
170→        fs::rename(&temp_path, &path)?;
171→
172→        Ok(())
173→    }
174→
175→    /// Get state for a step.
176→    pub fn get_step(&self, name: &str) -> Option<&StepState> {
177→        self.steps.get(name)
178→    }
179→
180→    /// Update state for a step.
181→    pub fn update_step(&mut self, name: &str, state: StepState) {
182→        self.steps.insert(name.to_string(), state);
183→    }
184→
185→    // --- Step State Tracking ---
186→
187→    /// Record a step execution result.
188→    pub fn record_step_result(
189→        &mut self,
190→        step: &str,
191→        status: StepStatus,
192→        duration: std::time::Duration,
193→        watches_hash: Option<String>,
194→    ) {
195→        let state = StepState {
196→            last_run: Some(Utc::now()),
197→            status,
198→            duration_ms: Some(duration.as_millis() as u64),
199→            watches_hash,
200→        };

  1→//! Local template loading from user and project directories.
  2→
  3→use crate::error::Result;
  4→use crate::registry::template::{Template, TemplateSource};
  5→use std::collections::HashMap;
  6→use std::fs;
  7→use std::path::{Path, PathBuf};
  8→
  9→/// Loader for local templates (user and project).
 10→#[derive(Debug, Clone)]
 11→pub struct LocalLoader {
 12→    templates: HashMap<String, (Template, TemplateSource)>,
 13→}
 14→
 15→impl LocalLoader {
 16→    /// Load templates from user and project directories.
 17→    pub fn new(project_root: Option<&Path>) -> Result<Self> {
 18→        let mut templates = HashMap::new();
 19→
 20→        // Load user templates (~/.bivvy/templates/)
 21→        if let Some(user_dir) = Self::user_templates_dir() {
 22→            Self::load_from_dir(&user_dir, TemplateSource::User, &mut templates)?;
 23→        }
 24→
 25→        // Load project templates (.bivvy/templates/)
 26→        if let Some(root) = project_root {
 27→            let project_dir = root.join(".bivvy").join("templates");
 28→            Self::load_from_dir(&project_dir, TemplateSource::Project, &mut templates)?;
 29→        }
 30→
 31→        Ok(Self { templates })
 32→    }
 33→
 34→    /// Get user templates directory.
 35→    fn user_templates_dir() -> Option<PathBuf> {
 36→        dirs::home_dir().map(|h| h.join(".bivvy").join("templates"))
 37→    }
 38→
 39→    /// Load templates from a directory (recursively).
 40→    fn load_from_dir(
 41→        dir: &Path,
 42→        source: TemplateSource,
 43→        templates: &mut HashMap<String, (Template, TemplateSource)>,
 44→    ) -> Result<()> {
 45→        if !dir.exists() {
 46→            return Ok(());
 47→        }
 48→
 49→        // Load from steps/ subdirectory
 50→        let steps_dir = dir.join("steps");
 51→        if steps_dir.exists() {
 52→            Self::load_templates_recursive(&steps_dir, source, templates)?;
 53→        }
 54→
 55→        Ok(())
 56→    }
 57→
 58→    fn load_templates_recursive(
 59→        dir: &Path,
 60→        source: TemplateSource,
 61→        templates: &mut HashMap<String, (Template, TemplateSource)>,
 62→    ) -> Result<()> {
 63→        if !dir.is_dir() {
 64→            return Ok(());
 65→        }
 66→
 67→        for entry in fs::read_dir(dir)? {
 68→            let entry = entry?;
 69→            let path = entry.path();
 70→
 71→            if path.is_dir() {
 72→                Self::load_templates_recursive(&path, source, templates)?;
 73→            } else if path
 74→                .extension()
 75→                .map(|e| e == "yml" || e == "yaml")
 76→                .unwrap_or(false)
 77→            {
 78→                let content = fs::read_to_string(&path)?;
 79→                let template: Template = serde_yaml::from_str(&content).map_err(|e| {
 80→                    crate::error::BivvyError::ConfigParseError {
 81→                        path: path.clone(),
 82→                        message: e.to_string(),
 83→                    }
 84→                })?;
 85→
 86→                // Project templates override user templates
 87→                if source == TemplateSource::Project || !templates.contains_key(&template.name) {
 88→                    templates.insert(template.name.clone(), (template, source));
 89→                }
 90→            }
 91→        }
 92→
 93→        Ok(())
 94→    }
 95→
 96→    /// Get a template by name.
 97→    pub fn get(&self, name: &str) -> Option<&Template> {
 98→        self.templates.get(name).map(|(t, _)| t)
 99→    }
100→

  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {
101→        self.project.is_some()
102→    }
103→}
104→
105→/// Find the project root by walking up from current directory.
106→///
107→/// Looks for:
108→/// 1. `.bivvy` directory (primary indicator)
109→/// 2. `.git` directory (fallback)
110→///
111→/// # Returns
112→///
113→/// The path to the project root, or None if not found.
114→pub fn find_project_root(start: &Path) -> Option<PathBuf> {
115→    let mut current = start.to_path_buf();
116→
117→    loop {
118→        // Check for .bivvy directory
119→        if current.join(".bivvy").is_dir() {
120→            return Some(current);
121→        }
122→
123→        // Check for .git directory (fallback)
124→        if current.join(".git").exists() {
125→            return Some(current);
126→        }
127→
128→        // Move up one directory
129→        if !current.pop() {
130→            return None;
131→        }
132→    }
133→}
134→
135→/// Load a single config file and parse it into BivvyConfig.
136→///
137→/// # Errors
138→///
139→/// Returns `ConfigNotFound` if the file doesn't exist.
140→/// Returns `ConfigParseError` if the YAML is invalid.
141→pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
142→    let content = fs::read_to_string(path).map_err(|e| {
143→        if e.kind() == std::io::ErrorKind::NotFound {
144→            BivvyError::ConfigNotFound {
145→                path: path.to_path_buf(),
146→            }
147→        } else {
148→            BivvyError::Io(e)
149→        }
150→    })?;

  1→//! Feedback storage (JSONL format).
  2→
  3→use std::fs::{self, File, OpenOptions};
  4→use std::io::{BufRead, BufReader, Write};
  5→use std::path::PathBuf;
  6→
  7→use anyhow::{Context, Result};
  8→
  9→use super::{FeedbackEntry, FeedbackStatus};
 10→use crate::session::SessionId;
 11→
 12→/// Storage for feedback entries.
 13→pub struct FeedbackStore {
 14→    path: PathBuf,
 15→}
 16→
 17→impl FeedbackStore {
 18→    /// Create a new feedback store.
 19→    pub fn new(path: impl Into<PathBuf>) -> Self {
 20→        Self { path: path.into() }
 21→    }
 22→
 23→    /// Get the store path.
 24→    pub fn path(&self) -> &PathBuf {
 25→        &self.path
 26→    }
 27→
 28→    /// Ensure the parent directory exists.
 29→    fn ensure_dir(&self) -> Result<()> {
 30→        if let Some(parent) = self.path.parent() {
 31→            fs::create_dir_all(parent)
 32→                .with_context(|| format!("Failed to create directory {:?}", parent))?;
 33→        }
 34→        Ok(())
 35→    }
 36→
 37→    /// Append a feedback entry.
 38→    pub fn append(&self, entry: &FeedbackEntry) -> Result<()> {
 39→        self.ensure_dir()?;
 40→
 41→        let mut file = OpenOptions::new()
 42→            .create(true)
 43→            .append(true)
 44→            .open(&self.path)
 45→            .with_context(|| format!("Failed to open {:?}", self.path))?;
 46→
 47→        let json = serde_json::to_string(entry)?;
 48→        writeln!(file, "{}", json)?;
 49→
 50→        Ok(())
 51→    }
 52→
 53→    /// List all feedback entries.
 54→    pub fn list_all(&self) -> Result<Vec<FeedbackEntry>> {
 55→        self.read_entries(|_| true)
 56→    }
 57→
 58→    /// List feedback by status.
 59→    pub fn list_by_status(&self, status: FeedbackStatus) -> Result<Vec<FeedbackEntry>> {
 60→        self.read_entries(|e| e.status == status)
 61→    }
 62→
 63→    /// List feedback by tag.
 64→    pub fn list_by_tag(&self, tag: &str) -> Result<Vec<FeedbackEntry>> {
 65→        self.read_entries(|e| e.tags.iter().any(|t| t == tag))
 66→    }
 67→
 68→    /// List feedback by session.
 69→    pub fn list_by_session(&self, session_id: &SessionId) -> Result<Vec<FeedbackEntry>> {
 70→        self.read_entries(|e| e.session_id.as_ref() == Some(session_id))
 71→    }
 72→
 73→    /// Update an entry by ID.
 74→    pub fn update(&self, id: &str, updater: impl FnOnce(&mut FeedbackEntry)) -> Result<bool> {
 75→        let mut entries = self.list_all()?;
 76→        let mut found = false;
 77→
 78→        for entry in &mut entries {
 79→            if entry.id == id {
 80→                updater(entry);
 81→                found = true;
 82→                break;
 83→            }
 84→        }
 85→
 86→        if found {
 87→            self.rewrite_all(&entries)?;
 88→        }
 89→
 90→        Ok(found)
 91→    }
 92→
 93→    /// Get an entry by ID.
 94→    pub fn get(&self, id: &str) -> Result<Option<FeedbackEntry>> {
 95→        let entries = self.read_entries(|e| e.id == id)?;
 96→        Ok(entries.into_iter().next())
 97→    }
 98→
 99→    /// Read entries matching a predicate.
100→    fn read_entries(
101→        &self,
102→        predicate: impl Fn(&FeedbackEntry) -> bool,
103→    ) -> Result<Vec<FeedbackEntry>> {
104→        if !self.path.exists() {
105→            return Ok(Vec::new());
106→        }
107→
108→        let file = File::open(&self.path)?;
109→        let reader = BufReader::new(file);
110→        let mut entries = Vec::new();
111→
112→        for line in reader.lines() {
113→            let line = line?;
114→            if line.trim().is_empty() {
115→                continue;
116→            }
117→            if let Ok(entry) = serde_json::from_str::<FeedbackEntry>(&line) {
118→                if predicate(&entry) {
119→                    entries.push(entry);
120→                }
121→            }
122→        }
123→
124→        Ok(entries)
125→    }
126→
127→    /// Rewrite all entries (for updates).
128→    fn rewrite_all(&self, entries: &[FeedbackEntry]) -> Result<()> {
129→        self.ensure_dir()?;
130→
131→        let mut file = File::create(&self.path)?;
132→        for entry in entries {
133→            let json = serde_json::to_string(entry)?;
134→            writeln!(file, "{}", json)?;
135→        }
136→
137→        Ok(())
138→    }
139→}
