  1→//! Template schema definitions.
  2→//!
  3→//! Templates are reusable step definitions that can be referenced
  4→//! from configuration files.
  5→
  6→use serde::{Deserialize, Serialize};
  7→use std::collections::HashMap;
  8→
  9→/// A reusable step template.
 10→#[derive(Debug, Clone, Serialize, Deserialize)]
 11→pub struct Template {
 12→    /// Template name (must be unique within source)
 13→    pub name: String,
 14→
 15→    /// Human-readable description
 16→    pub description: String,
 17→
 18→    /// Category for organization (e.g., "ruby", "node", "common")
 19→    pub category: String,
 20→
 21→    /// Semantic version
 22→    #[serde(default = "default_version")]
 23→    pub version: String,
 24→
 25→    /// Minimum Bivvy version required
 26→    pub min_bivvy_version: Option<String>,
 27→
 28→    /// Platforms this template supports
 29→    #[serde(default = "default_platforms")]
 30→    pub platforms: Vec<Platform>,
 31→
 32→    /// Detection rules to suggest this template
 33→    #[serde(default)]
 34→    pub detects: Vec<Detection>,
 35→
 36→    /// Input contracts for this template
 37→    #[serde(default)]
 38→    pub inputs: HashMap<String, TemplateInput>,
 39→
 40→    /// The step configuration this template provides
 41→    pub step: TemplateStep,
 42→
 43→    /// Environment impact after this step runs
 44→    pub environment_impact: Option<EnvironmentImpact>,
 45→}
 46→
 47→fn default_version() -> String {
 48→    "1.0.0".to_string()
 49→}
 50→
 51→fn default_platforms() -> Vec<Platform> {
 52→    vec![Platform::MacOS, Platform::Linux, Platform::Windows]
 53→}
 54→
 55→/// Supported platforms.
 56→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 57→#[serde(rename_all = "lowercase")]
 58→pub enum Platform {
 59→    MacOS,
 60→    Linux,
 61→    Windows,
 62→}
 63→
 64→impl Platform {
 65→    /// Check if current platform matches.
 66→    pub fn is_current(&self) -> bool {
 67→        match self {
 68→            Platform::MacOS => cfg!(target_os = "macos"),
 69→            Platform::Linux => cfg!(target_os = "linux"),
 70→            Platform::Windows => cfg!(target_os = "windows"),
 71→        }
 72→    }
 73→}
 74→
 75→/// Detection rule for auto-suggesting templates.
 76→#[derive(Debug, Clone, Serialize, Deserialize)]
 77→pub struct Detection {
 78→    /// File that indicates this template applies
 79→    pub file: Option<String>,
 80→
 81→    /// Command that must succeed (exit 0)
 82→    pub command: Option<String>,
 83→}
 84→
 85→/// Template input contract for parameterized templates.
 86→#[derive(Debug, Clone, Serialize, Deserialize)]
 87→pub struct TemplateInput {
 88→    /// Human-readable description
 89→    pub description: String,
 90→
 91→    /// Input type
 92→    #[serde(rename = "type")]
 93→    pub input_type: InputType,
 94→
 95→    /// Whether this input is required
 96→    #[serde(default)]
 97→    pub required: bool,
 98→
 99→    /// Default value if not provided
100→    pub default: Option<serde_yaml::Value>,
101→
102→    /// Valid values for enum type
103→    #[serde(default)]
104→    pub values: Vec<String>,
105→}
106→
107→impl TemplateInput {
108→    /// Validate a provided value against this input contract.
109→    pub fn validate(&self, name: &str, value: Option<&serde_yaml::Value>) -> Result<(), String> {
110→        match value {
111→            None => {
112→                if self.required && self.default.is_none() {
113→                    Err(format!("Required input '{}' is missing", name))
114→                } else {
115→                    Ok(())
116→                }
117→            }
118→            Some(v) => self.validate_type(name, v),
119→        }
120→    }
121→
122→    fn validate_type(&self, name: &str, value: &serde_yaml::Value) -> Result<(), String> {
123→        match self.input_type {
124→            InputType::String => {
125→                if !value.is_string() {
126→                    return Err(format!("Input '{}' must be a string", name));
127→                }
128→            }
129→            InputType::Number => {
130→                if !value.is_number() {
131→                    return Err(format!("Input '{}' must be a number", name));
132→                }
133→            }
134→            InputType::Boolean => {
135→                if !value.is_bool() {
136→                    return Err(format!("Input '{}' must be a boolean", name));
137→                }
138→            }
139→            InputType::Enum => {
140→                let s = value
141→                    .as_str()
142→                    .ok_or_else(|| format!("Input '{}' must be a string (enum)", name))?;
143→                if !self.values.contains(&s.to_string()) {
144→                    return Err(format!(
145→                        "Input '{}' must be one of: {}",
146→                        name,
147→                        self.values.join(", ")
148→                    ));
149→                }
150→            }
151→        }
152→        Ok(())
153→    }
154→
155→    /// Get effective value (provided or default).
156→    pub fn effective_value<'a>(
157→        &'a self,
158→        provided: Option<&'a serde_yaml::Value>,
159→    ) -> Option<&'a serde_yaml::Value> {
160→        provided.or(self.default.as_ref())
161→    }
162→}
163→
164→/// Types of template inputs.
165→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
166→#[serde(rename_all = "lowercase")]
167→pub enum InputType {
168→    String,
169→    Number,
170→    Boolean,
171→    Enum,
172→}
173→
174→/// Step configuration provided by a template.
175→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
176→#[serde(default)]
177→pub struct TemplateStep {
178→    /// Step title (supports interpolation)
179→    pub title: Option<String>,
180→
181→    /// Step description
182→    pub description: Option<String>,
183→
184→    /// Command to execute
185→    pub command: Option<String>,
186→
187→    /// Completed check configuration
188→    pub completed_check: Option<crate::config::CompletedCheck>,
189→
190→    /// Environment variables
191→    #[serde(default)]
192→    pub env: HashMap<String, String>,
193→
194→    /// Files to watch for change detection
195→    #[serde(default)]
196→    pub watches: Vec<String>,
197→
198→    /// System-level prerequisites this template's step requires.
199→    #[serde(default)]
200→    pub requires: Vec<String>,
201→}
202→
203→/// Environment impact after a step runs.
204→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
205→#[serde(default)]
206→pub struct EnvironmentImpact {
207→    /// Whether this step modifies PATH
208→    #[serde(default)]
209→    pub modifies_path: bool,
210→
211→    /// Shell config files that may be modified
212→    #[serde(default)]
213→    pub shell_files: Vec<String>,
214→
215→    /// Paths that will be added to PATH
216→    #[serde(default)]
217→    pub path_additions: Vec<String>,
218→
219→    /// Note to display to user
220→    pub note: Option<String>,
221→}
222→
223→/// Source of a template (for priority ordering).
224→#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
225→pub enum TemplateSource {
226→    /// Project-local templates (.bivvy/templates/)
227→    Project,
228→    /// User-local templates (~/.bivvy/templates/)
229→    User,
230→    /// Remote templates (URL-based)
231→    Remote {
232→        /// Priority for remote sources (lower is higher priority)
233→        priority: u32,
234→    },
235→    /// Built-in templates (embedded in binary)
236→    Builtin,
237→}
